/* studio: css module src/screens/ESimActivation.module.css */
.ESimActivation_frame__1afee {
  max-width: 390px;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  font-family: "Open Sans", sans-serif;
  color: var(--color-metal);
  background: #000;
}

.ESimActivation_statusBar__1364b {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 24px 12px;
  background: #000;
  color: #fff;
}

.ESimActivation_statusTime__591b1 {
  font-size: 15px;
  font-weight: 600;
  color: #fff;
}

.ESimActivation_statusIcons__de421 {
  display: flex;
  align-items: center;
  gap: 6px;
}

.ESimActivation_screen__290b3 {
  background-color: var(--color-light);
  display: flex;
  flex-direction: column;
  flex: 1;
  border-top-left-radius: 20px;
  border-top-right-radius: 20px;
  overflow: hidden;
  padding-bottom: 16px;
}

/* ── Header ── */
.ESimActivation_header__32c4f {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 16px 8px;
}

.ESimActivation_closeLink__63d61 {
  color: var(--color-aqua-100);
  font-size: 16px;
  font-weight: 400;
  min-width: 60px;
  cursor: pointer;
}

.ESimActivation_headerTitle__3d36a {
  font-size: 17px;
  font-weight: 700;
  color: var(--color-metal);
  margin: 0;
  text-align: center;
  flex: 1;
}

.ESimActivation_headerSpacer__55d57 {
  min-width: 60px;
}

/* ── Hero ── */
.ESimActivation_hero__637c5 {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 20px 24px 24px;
  gap: 6px;
}

.ESimActivation_brandIcons__25ab5 {
  display: flex;
  align-items: center;
  margin-bottom: 14px;
}

.ESimActivation_airlineBadge__280f9 {
  border-radius: 50%;
  z-index: 1;
  display: flex;
}

.ESimActivation_checkBadge__c8a39 {
  margin-left: -10px;
  border-radius: 50%;
  border: 3px solid var(--color-light);
  z-index: 2;
  display: flex;
}

.ESimActivation_heroTitle__218f8 {
  font-size: 20px;
  font-weight: 700;
  color: var(--color-metal);
  margin: 0;
  text-align: center;
}

.ESimActivation_heroSubtitle__fa33e {
  font-size: 14px;
  color: var(--color-chateau);
  margin: 0 0 16px;
  text-align: center;
}

/* ── Sections ── */
.ESimActivation_section__d8db6 {
  padding: 20px 16px 8px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.ESimActivation_sectionTitle__c3cec {
  font-size: 18px;
  font-weight: 700;
  color: var(--color-metal);
  margin: 0 0 4px;
}

/* ── Cards ── */
.ESimActivation_card__51026 {
  background-color: var(--color-light);
  border: 1px solid var(--color-gainsboro);
  border-radius: 12px;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.ESimActivation_cardBadge__645aa {
  display: flex;
  margin: -4px 0 -2px;
}

.ESimActivation_cardRow__86447 {
  display: flex;
  gap: 14px;
  align-items: center;
}

.ESimActivation_illoWrap__e9065 {
  flex-shrink: 0;
  width: 64px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.ESimActivation_cardText__cf489 {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.ESimActivation_cardTitle__da943 {
  font-size: 15px;
  font-weight: 700;
  color: var(--color-metal);
  line-height: 1.3;
}

.ESimActivation_cardSubtext__d6784 {
  font-size: 13px;
  color: var(--color-chateau);
  margin: 0;
  line-height: 1.4;
}

.ESimActivation_cardFooter__a3163 {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.ESimActivation_cardCode__6aeb4 {
  font-size: 14px;
  color: var(--color-metal);
}

/* ── Add-ons ── */
.ESimActivation_addonRow__856fc {
  display: flex;
  align-items: center;
  gap: 14px;
}

.ESimActivation_simWrap__e1727 {
  flex-shrink: 0;
  width: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.ESimActivation_addonText__5018f {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.ESimActivation_addonTitle__f7fd8 {
  font-size: 16px;
  font-weight: 700;
  color: var(--color-metal);
}

.ESimActivation_addonSubtext__e0c97 {
  font-size: 13px;
  color: var(--color-chateau);
  margin: 0;
  line-height: 1.4;
}

/* ── Outlined pill button ── */
.ESimActivation_outlinePill__b32b6 {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 9px 22px;
  border-radius: 999px;
  background: #fff;
  color: var(--color-aqua-100, #009BAE);
  border: 1.5px solid var(--color-aqua-100, #009BAE);
  font-family: inherit;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.2;
  white-space: nowrap;
  cursor: pointer;
}

.ESimActivation_outlinePillLarge__aaf86 {
  padding: 13px 38px;
  font-size: 16px;
}

/* ── Aqua tinted tag ── */
.ESimActivation_aquaTag__22f42 {
  display: inline-flex;
  align-items: center;
  padding: 5px 12px;
  border-radius: 6px;
  background: #DFF0F3;
  color: var(--color-aqua-100, #009BAE);
  font-size: 13px;
  font-weight: 400;
  line-height: 1.2;
}


/* studio: css module src/screens/Page2.module.css */
/* Fluid by default: fills the frame it is placed in and caps for
   readability on wide viewports. Never a fixed width — a screen pinned to one
   device size stops being a design and becomes a screenshot. */
.Page2_page__d038d {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.5rem;
  width: 100%;
  max-width: 60rem;
  margin-inline: auto;
  padding: clamp(1.5rem, 5vw, 4rem);
}

.Page2_title__9572c {
  margin: 0;
  font-size: clamp(1.5rem, 4vw, 2rem);
  font-weight: 700;
}

/* currentColor rather than a literal: inherits whatever the project already
   uses, so the starter never introduces an off-palette hex. */
.Page2_subtitle__bba20 {
  margin: 0;
  color: currentColor;
  opacity: 0.65;
}
